        vm.startPrank(owner);

        // First, ensure attacker has some MSA tokens to work with
        // The owner initially has all tokens, so transfer some to attacker
        MyShibaAcademia(TARGET).transfer(attacker, 100_000 * 10**9);

        // Also transfer some to victim for triggering fees
        MyShibaAcademia(TARGET).transfer(victim, 50_000 * 10**9);

        // Stop prank
        vm.stopPrank();
    }

